#include "exotic/autonomy/agents/in_memory_repository.hpp"
#include "exotic/autonomy/agents/router.hpp"
#include <cassert>
using namespace exotic::autonomy;using namespace exotic::autonomy::agents;
int main(){InMemoryAgentRepository repo;AgentRegistry registry{repo};CapabilityDefinition d;d.key="ops";d.name="Ops";registry.define_capability(d);auto make=[&](std::string key,double score){AgentIdentity a;a.identity_key=key;a.display_name=key;a.health=HealthState::Healthy;a.trust=TrustLevel::Elevated;a.workload.maximum_tasks=1;auto id=registry.register_agent(a);registry.activate(id);registry.grant_capability({id,"ops",score,score,0,0,Clock::now()});return id;};auto first=make("first",0.95);auto second=make("second",0.90);AllowAllGovernanceCompatibility gov;AllowAllResourceCompatibility res;CandidateScorer scorer{repo,registry,gov,res};WorkAllocator allocator{repo,scorer};TaskRequirement req;req.job_id=3;req.proposal_id=3;req.capabilities={{"ops",0.8,0.8,true,1.0}};auto initial=allocator.allocate(req);assert(initial.allocated&&initial.assignment);assert(initial.assignment->plan.agent_ids.front()==first);const auto continuity=initial.assignment->continuity_key;const auto version=initial.assignment->version;registry.set_availability(first,Availability::Unavailable);auto replacement=allocator.replace(initial.assignment->id,first,"worker failed");assert(replacement.allocated&&replacement.assignment);assert(replacement.assignment->id==initial.assignment->id);assert(replacement.assignment->continuity_key==continuity);assert(replacement.assignment->version==version+1);assert(replacement.assignment->plan.agent_ids.front()==second);return 0;}
